import type { Transition } from "motion/react";

export const easeOut = [0.23, 1, 0.32, 1] as const;

export const easeInOut = [0.77, 0, 0.175, 1] as const;

export const duration = {
  fast: 0.14,
  base: 0.2,
  slow: 0.28,
} as const;

export const springSnappy = {
  type: "spring",
  duration: 0.24,
  bounce: 0,
} as const satisfies Transition;

export const springLayout = {
  type: "spring",
  duration: 0.3,
  bounce: 0,
} as const satisfies Transition;

export function transitionFor(
  reduceMotion: boolean | null,
  transition: Transition,
): Transition {
  return reduceMotion ? { duration: 0 } : transition;
}

import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

"use client";

import {
  AnimatePresence,
  type HTMLMotionProps,
  motion,
  useIsPresent,
  useReducedMotion,
} from "motion/react";
import type { ReactNode } from "react";
import { duration as durations, easeOut, transitionFor } from "./motion";
import { cn } from "./utils";

export interface PresenceProps
  extends Omit<
    HTMLMotionProps<"div">,
    "ref" | "children" | "initial" | "animate" | "exit" | "transition"
  > {
  show: boolean;
  children: ReactNode;
  as?: "div" | "span";
  distance?: number;
  duration?: number;
}

function PresenceContent({
  as,
  children,
  className,
  distance = 8,
  duration = durations.base,
  ...props
}: Omit<PresenceProps, "show">) {
  const isPresent = useIsPresent();
  const reducedMotion = useReducedMotion();
  const Element = as === "span" ? motion.span : motion.div;

  return (
    <Element
      {...props}
      data-slot="presence"
      className={cn(as === "span" && "inline-block", className)}
      inert={!isPresent}
      aria-hidden={!isPresent || undefined}
      initial={reducedMotion ? false : { opacity: 0, y: distance }}
      animate={{ opacity: 1, y: 0 }}
      exit={
        reducedMotion
          ? { opacity: 0, transition: { duration: 0 } }
          : {
              opacity: 0,
              y: -distance,
              transition: { duration: duration * 0.7, ease: easeOut },
            }
      }
      transition={transitionFor(reducedMotion, { duration, ease: easeOut })}
    >
      {children}
    </Element>
  );
}

export function Presence({ show, ...props }: PresenceProps) {
  return (
    <AnimatePresence initial={false}>
      {show && <PresenceContent key="content" {...props} />}
    </AnimatePresence>
  );
}
